//go:build ignore

// Gen compiles shader.metal into a Metal library with Xcode's metal tools
// and writes shaderlib.go, so that renderers start without compiling the
// shader, which takes over 100 ms until Metal has cached it. It runs on
// macOS with Xcode: go generate ./internal/gpu/metal
package main

import (
	"bytes"
	"fmt"
	"go/format"
	"log"
	"os"

	"github.com/egoist/mygo/internal/gpu"
	"github.com/egoist/mygo/internal/gpu/metal"
)

func main() {
	src, err := os.ReadFile("shader.metal")
	if err != nil {
		log.Fatal(err)
	}
	code, err := metal.CompileLibrary(string(src))
	if err != nil {
		log.Fatal(err)
	}
	var b bytes.Buffer
	fmt.Fprintf(&b, "// Code generated by gen.go from shader.metal; DO NOT EDIT.\n\n//go:build darwin\n\npackage metal\n\n")
	fmt.Fprintf(&b, "// shaderLibrarySum is the SHA-256 of the shader.metal shaderLibrary was\n// compiled from.\nconst shaderLibrarySum = %q\n\n", gpu.SourceSum(string(src)))
	b.WriteString(gpu.GoBytes("shaderLibrary", code))
	out, err := format.Source(b.Bytes())
	if err != nil {
		log.Fatal(err)
	}
	if err := os.WriteFile("shaderlib.go", out, 0o644); err != nil {
		log.Fatal(err)
	}
}
